import React, { useState, useEffect, useRef } from 'react';
import { useParams, useLocation } from 'react-router-dom';
import { collection, addDoc, query, where, onSnapshot, serverTimestamp, doc, getDoc, updateDoc, orderBy } from 'firebase/firestore';
import { db, auth } from '../../firebase';
import { onAuthStateChanged } from 'firebase/auth';
import CryptoJS from 'crypto-js';

const ChatPage = () => {
    const { postId } = useParams();
    const location = useLocation();
    const listing = location.state?.listing;
    const initialRecipientId = location.state?.recipientId;
    const initialConversationId = location.state?.conversationId;

    const [user, setUser] = useState(null);
    const [messages, setMessages] = useState([]);
    const [newMessage, setNewMessage] = useState('');
    const [recipientId, setRecipientId] = useState(initialRecipientId);
    const [recipientName, setRecipientName] = useState('');
    const [conversationId, setConversationId] = useState(initialConversationId || '');
    const messagesEndRef = useRef(null);

    const secretKey = 'Kibzar';

    useEffect(() => {
        const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
            setUser(currentUser);
        });
        return () => unsubscribe();
    }, []);

    useEffect(() => {
        const fetchRecipientDetails = async () => {
            if (recipientId) {
                try {
                    const recipientDoc = await getDoc(doc(db, 'users', recipientId));
                    if (recipientDoc.exists()) {
                        setRecipientName(recipientDoc.data().name);
                    }
                } catch (error) {
                    console.error('Error fetching recipient details: ', error);
                }
            }
        };
        fetchRecipientDetails();
    }, [recipientId]);

    useEffect(() => {
        if (user && recipientId && !initialConversationId) {
            const uniqueUsers = [user.uid, recipientId].sort();
            setConversationId([...uniqueUsers, postId].join('_'));
        }
    }, [user, recipientId, postId, initialConversationId]);

    useEffect(() => {
        if (user && recipientId && conversationId) {
            const q = query(
                collection(db, 'chats'),
                where('conversationId', '==', conversationId),
                orderBy('timestamp', 'asc')
            );

            const unsubscribe = onSnapshot(q, async (snapshot) => {
                const msgs = snapshot.docs.map((doc) => {
                    const data = doc.data();
                    const decryptedMessage = CryptoJS.AES.decrypt(data.message, secretKey).toString(CryptoJS.enc.Utf8);
                    return { ...data, message: decryptedMessage };
                });
                setMessages(msgs);
                messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
            });

            return () => unsubscribe();
        }
    }, [user, recipientId, conversationId]);

    const handleSendMessage = async (e) => {
        e.preventDefault();
        if (newMessage.trim() === '') return;

        const encryptedMessage = CryptoJS.AES.encrypt(newMessage, secretKey).toString();

        try {
            await addDoc(collection(db, 'chats'), {
                postId,
                userId: user.uid,
                recipientId,
                conversationId,
                message: encryptedMessage,
                timestamp: serverTimestamp(),
            });
            setNewMessage('');
        } catch (error) {
            console.error('Error sending message: ', error);
        }
    };

    return (
        <div className="container mx-auto px-4 py-6 flex flex-col h-screen bg-gray-50">
            <header className="flex items-center justify-between bg-white shadow-md p-4 rounded-md mb-4">
                <h1 className="text-xl font-semibold">Chat with {recipientName}</h1>
                <span className="text-sm text-gray-500">Listing: {listing?.title || 'N/A'}</span>
            </header>

            {listing && (
                <div className="bg-white p-4 rounded-lg shadow-md flex items-center mb-4">
                    {listing.imageUrl && (
                        <img
                            src={listing.imageUrl[0]}
                            alt={listing.title}
                            className="w-16 h-16 object-cover rounded-md mr-4"
                        />
                    )}
                    <div>
                        <h2 className="text-lg font-semibold">{listing.title}</h2>
                        <p className="text-sm text-gray-600">{listing.description}</p>
                    </div>
                </div>
            )}

            <div className="flex-grow overflow-y-auto bg-white rounded-lg shadow-md p-4 mb-4">
                {messages.length > 0 ? (
                    messages.map((msg, index) => (
                        <div
                            key={index}
                            className={`flex mb-3 ${msg.userId === user.uid ? 'justify-end' : 'justify-start'}`}
                        >
                            <div
                                className={`max-w-xs p-3 rounded-lg shadow-md ${
                                    msg.userId === user.uid
                                        ? 'bg-blue-500 text-white'
                                        : 'bg-gray-200 text-black'
                                }`}
                            >
                                <p>{msg.message}</p>
                                <p className="text-xs text-gray-500 mt-1 text-right">
                                    {msg.timestamp?.toDate().toLocaleTimeString([], {
                                        hour: '2-digit',
                                        minute: '2-digit',
                                    })}
                                </p>
                            </div>
                        </div>
                    ))
                ) : (
                    <p className="text-gray-500 text-center">No messages yet.</p>
                )}
                <div ref={messagesEndRef} />
            </div>

            <form onSubmit={handleSendMessage} className="flex items-center bg-white shadow-md rounded-md">
                <input
                    type="text"
                    value={newMessage}
                    onChange={(e) => setNewMessage(e.target.value)}
                    placeholder="Type your message..."
                    className="flex-grow p-3 rounded-l-md border border-gray-300 focus:outline-none"
                />
                <button
                    type="submit"
                    className="bg-blue-500 text-white px-4 py-2 rounded-r-md hover:bg-blue-600 transition"
                >
                    Send
                </button>
            </form>
        </div>
    );
};

export default ChatPage;
